2009	+
2010	+class MockAccountRemoteDataSource extends Mock
2011	+    implements AccountRemoteDataSource {}
2012	+
2013	+/// Covers spec-2-4's I/O & Edge-Case Matrix exactly:
2014	+/// - boot fetch resolves `false`/`true` -> `currentBiometricEnabled`/
2015	+///   `biometricEnabledStream` updated.
2016	+/// - boot fetch fails -> swallowed, `currentBiometricEnabled` unchanged.
2017	+/// - toggle succeeds -> flips immediately, persists, no error.
2018	+/// - toggle fails -> reverts to the prior value, `Left(Failure)` returned
2019	+///   so the caller can surface its message.
2020	+void main() {
2021	+  late MockAccountRemoteDataSource mockRemoteDataSource;
2022	+  late AccountSettingsRepositoryImpl repository;
2023	+
2024	+  setUp(() {
2025	+    mockRemoteDataSource = MockAccountRemoteDataSource();
2026	+    repository = AccountSettingsRepositoryImpl(
2027	+      remoteDataSource: mockRemoteDataSource,
2028	+    );
2029	+  });
2030	+
2031	+  tearDown(() => repository.dispose());
2032	+
2033	+  /// Same rationale as `vault_repository_impl_test.dart`'s own
2034	+  /// `emittedDuring` helper: `biometricEnabledStream` always synchronously
2035	+  /// replays the current value to a brand-new listener, so that replay is
2036	+  /// drained and discarded here first.
2037	+  Future<List<bool>> emittedDuring(Future<void> Function() act) async {
2038	+    final emitted = <bool>[];
2039	+    final subscription = repository.biometricEnabledStream.listen(
2040	+      emitted.add,
2041	+    );
2042	+    await Future<void>.delayed(Duration.zero);
2043	+    emitted.clear();
2044	+    await act();
2045	+    await Future<void>.delayed(Duration.zero);
2046	+    await subscription.cancel();
2047	+    return emitted;
2048	+  }
2049	+
2050	+  group('currentBiometricEnabled — starts true, never null (Boundaries)', () {
2051	+    test('currentBiometricEnabled is true before any fetch/toggle call', () {
2052	+      expect(repository.currentBiometricEnabled, isTrue);
2053	+    });
2054	+
2055	+    test('a listener that subscribes before any call still immediately '
2056	+        'sees true, not nothing until the first emission (Stream.multi '
2057	+        'replay)', () async {
2058	+      final value = await repository.biometricEnabledStream.first;
2059	+
2060	+      expect(value, isTrue);
2061	+    });
2062	+  });
2063	+
2064	+  group('fetchBiometricEnabled() — boot fetch', () {
2065	+    test('resolves false -> currentBiometricEnabled/stream update to false',
2066	+        () async {
2067	+      when(() => mockRemoteDataSource.fetchSettings()).thenAnswer(
2068	+        (_) async => right(const AccountSettingsDto(biometricEnabled: false)),
2069	+      );
2070	+
2071	+      Either<Failure, Unit>? result;
2072	+      final emitted = await emittedDuring(() async {
2073	+        result = await repository.fetchBiometricEnabled();
2074	+      });
2075	+
2076	+      expect(emitted, [false]);
2077	+      expect(repository.currentBiometricEnabled, isFalse);
2078	+      expect(result!.isRight(), isTrue);
2079	+    });
2080	+
2081	+    test('resolves true -> currentBiometricEnabled/stream update to true '
2082	+        '(still true, but goes through the real emit path, not just the '
2083	+        'untouched default)', () async {
2084	+      when(() => mockRemoteDataSource.fetchSettings()).thenAnswer(
2085	+        (_) async => right(const AccountSettingsDto(biometricEnabled: true)),
2086	+      );
2087	+
2088	+      Either<Failure, Unit>? result;
2089	+      final emitted = await emittedDuring(() async {
2090	+        result = await repository.fetchBiometricEnabled();
2091	+      });
2092	+
2093	+      expect(emitted, [true]);
2094	+      expect(repository.currentBiometricEnabled, isTrue);
2095	+      expect(result!.isRight(), isTrue);
2096	+    });
2097	+
2098	+    test('fails -> currentBiometricEnabled unchanged, no emission, '
2099	+        'Left(Failure) returned (swallowed by the caller, fire-and-forget '
2100	+        'like restoreSession())', () async {
2101	+      when(() => mockRemoteDataSource.fetchSettings()).thenAnswer(
2102	+        (_) async => left(const Failure.networkOffline(message: 'offline')),
2103	+      );
2104	+
2105	+      Either<Failure, Unit>? result;
2106	+      final emitted = await emittedDuring(() async {
2107	+        result = await repository.fetchBiometricEnabled();
2108	+      });
2109	+
2110	+      expect(emitted, isEmpty);
2111	+      expect(repository.currentBiometricEnabled, isTrue);
2112	+      expect(result!.isLeft(), isTrue);
2113	+    });
2114	+  });
2115	+
2116	+  group('setBiometricEnabled() — optimistic toggle', () {
2117	+    test('succeeds -> flips immediately (before the PATCH call resolves) '
2118	+        'and stays flipped, Right(unit) returned', () async {
2119	+      final patchCompleter = Completer<Either<Failure, AccountSettingsDto>>();
2120	+      when(
2121	+        () => mockRemoteDataSource.updateBiometricEnabled(false),
2122	+      ).thenAnswer((_) => patchCompleter.future);
2123	+
2124	+      final emitted = <bool>[];
2125	+      final subscription = repository.biometricEnabledStream.listen(
2126	+        emitted.add,
2127	+      );
2128	+      await Future<void>.delayed(Duration.zero);
2129	+      emitted.clear();
2130	+
2131	+      final resultFuture = repository.setBiometricEnabled(false);
2132	+      // The flip already happened synchronously, before the PATCH call's
2133	+      // own Future even resolves (RNF01, <100ms — Boundaries).
2134	+      await Future<void>.delayed(Duration.zero);
2135	+      expect(repository.currentBiometricEnabled, isFalse);
2136	+      expect(emitted, [false]);
2137	+
2138	+      patchCompleter.complete(
2139	+        right(const AccountSettingsDto(biometricEnabled: false)),
2140	+      );
2141	+      final result = await resultFuture;
2142	+      await subscription.cancel();
2143	+
2144	+      expect(result.isRight(), isTrue);
2145	+      expect(repository.currentBiometricEnabled, isFalse);
2146	+    });
2147	+
2148	+    test('fails -> reverts to the prior value, Left(Failure) returned so '
2149	+        'the caller can show the message inline', () async {
2150	+      // Starts true (default) -> toggling to false, then the PATCH fails.
2151	+      when(() => mockRemoteDataSource.updateBiometricEnabled(false)).thenAnswer(
2152	+        (_) async =>
2153	+            left(const Failure.networkTimeout(message: 'fake: timed out')),
2154	+      );
2155	+
2156	+      Either<Failure, Unit>? result;
2157	+      final emitted = await emittedDuring(() async {
2158	+        result = await repository.setBiometricEnabled(false);
2159	+      });
2160	+
2161	+      // Optimistic flip to false, then reverted back to true.
2162	+      expect(emitted, [false, true]);
2163	+      expect(repository.currentBiometricEnabled, isTrue);
2164	+      expect(result!.isLeft(), isTrue);
2165	+      result!.match(
2166	+        (failure) => expect(failure, isA<NetworkTimeout>()),
2167	+        (_) => fail('expected Left'),
2168	+      );
2169	+    });
2170	+
2171	+    test('calls the data source with exactly the requested value', () async {
2172	+      when(() => mockRemoteDataSource.updateBiometricEnabled(true)).thenAnswer(
2173	+        (_) async =>
2174	+            right(const AccountSettingsDto(biometricEnabled: true)),
2175	+      );
2176	+
2177	+      await repository.setBiometricEnabled(true);
2178	+
2179	+      verify(() => mockRemoteDataSource.updateBiometricEnabled(true))
2180	+          .called(1);
2181	+    });
2182	+  });
2183	+
2184	+  group('dispose()', () {
2185	+    test('closes the underlying stream — a subsequent fetch/toggle never '
2186	+        'throws trying to emit on a closed controller, the attempted emit '
2187	+        'is a silent no-op', () async {
2188	+      when(() => mockRemoteDataSource.fetchSettings()).thenAnswer(
2189	+        (_) async => right(const AccountSettingsDto(biometricEnabled: false)),
2190	+      );
2191	+
2192	+      await repository.dispose();
2193	+
2194	+      final result = await repository.fetchBiometricEnabled();
2195	+
2196	+      expect(result.isRight(), isTrue);
2197	+      // The emit attempt was a no-op since the controller is already
2198	+      // closed — currentBiometricEnabled stays at whatever it was before
2199	+      // dispose() (still the default true).
2200	+      expect(repository.currentBiometricEnabled, isTrue);
2201	+    });
2202	+
2203	+    test('a subsequent setBiometricEnabled() also never throws trying to '
2204	+        'emit on a closed controller — covers the optimistic-flip side of '
2205	+        'the same guard, not just fetchBiometricEnabled()\'s', () async {
2206	+      when(() => mockRemoteDataSource.updateBiometricEnabled(false)).thenAnswer(
2207	+        (_) async =>
2208	+            right(const AccountSettingsDto(biometricEnabled: false)),
2209	+      );
2210	+
2211	+      await repository.dispose();
2212	+
2213	+      final result = await repository.setBiometricEnabled(false);
2214	+
2215	+      expect(result.isRight(), isTrue);
2216	+      // Both the optimistic flip and the (here, unreached) revert path
2217	+      // attempt to emit on an already-closed controller — a silent no-op,
2218	+      // same as fetchBiometricEnabled()'s own case above.
2219	+      expect(repository.currentBiometricEnabled, isTrue);
2220	+    });
2221	+  });
