2312	+/// `setBiometricEnabled()` result plus a real stream the cubit actually
2313	+/// subscribes to, which a mocktail stub can't give as naturally.
2314	+class _FakeAccountSettingsRepository implements AccountSettingsRepository {
2315	+  bool _value = true;
2316	+  final _controller = StreamController<bool>.broadcast();
2317	+
2318	+  /// The next `setBiometricEnabled()` call's own result — defaults to a
2319	+  /// failure so a test must opt in to the success path explicitly.
2320	+  Either<Failure, Unit> setBiometricEnabledResult = left(
2321	+    const Failure.malformedResponse(message: 'fake: not configured'),
2322	+  );
2323	+
2324	+  int setBiometricEnabledCallCount = 0;
2325	+
2326	+  @override
2327	+  bool get currentBiometricEnabled => _value;
2328	+
2329	+  @override
2330	+  Stream<bool> get biometricEnabledStream {
2331	+    return Stream<bool>.multi((controller) {
2332	+      controller.add(_value);
2333	+      final subscription = _controller.stream.listen(
2334	+        controller.add,
2335	+        onError: controller.addError,
2336	+        onDone: controller.close,
2337	+      );
2338	+      controller.onCancel = subscription.cancel;
2339	+    }, isBroadcast: true);
2340	+  }
2341	+
2342	+  @override
2343	+  Future<Either<Failure, Unit>> fetchBiometricEnabled() async =>
2344	+      right(unit);
2345	+
2346	+  @override
2347	+  Future<Either<Failure, Unit>> setBiometricEnabled(bool enabled) async {
2348	+    setBiometricEnabledCallCount += 1;
2349	+    final previous = _value;
2350	+    _emit(enabled);
2351	+    final result = setBiometricEnabledResult;
2352	+    if (result.isLeft()) {
2353	+      _emit(previous);
2354	+    }
