2356	+  }
2357	+
2358	+  @override
2359	+  Future<void> dispose() => _controller.close();
2360	+
2361	+  void _emit(bool value) {
2362	+    _value = value;
2363	+    _controller.add(value);
2364	+  }
2365	+}
