2367	+Future<List<AccountSettingsState>> _emittedDuring(
2368	+  AccountSettingsCubit cubit,
2369	+  Future<void> Function() act,
2370	+) async {
2371	+  final emitted = <AccountSettingsState>[];
2372	+  final subscription = cubit.stream.listen(emitted.add);
2373	+  await act();
2374	+  // `pumpEventQueue()` (not a single `Future.delayed(Duration.zero)`): the
2375	+  // `biometricEnabled` mirror travels repository -> Stream.multi's own
2376	+  // forwarding subscription -> cubit's `emit()` -> `_stateController`,
2377	+  // several microtask hops deep — one `Duration.zero` delay only guarantees
2378	+  // draining one hop, leaving a later hop's delivery to land after this
2379	+  // helper already returned.
2380	+  await pumpEventQueue();
2381	+  await subscription.cancel();
2382	+  return emitted;
2383	+}
