144	  @override
145	  void didUpdateWidget(covariant VaultLockScreen oldWidget) {
146	    super.didUpdateWidget(oldWidget);
147	    // Review finding: `attemptBiometricFirst` was only ever consulted
148	    // once, in `initState` — defensive future-proofing in case this
149	    // already-mounted widget is ever rebuilt with a new value (today,
150	    // nothing actually does: `app_router.dart` reads `currentBiometricEnabled`
151	    // fresh only when `/vault` is newly built, not while already resident
152	    // there — see its own doc comment). If that ever changes, e.g. a boot-
153	    // time `fetchBiometricEnabled()` resolving to `false` while `/vault` is
154	    // already mounted (with the default `true`) and already auto-triggered
155	    // the OS biometric prompt: that in-flight prompt can't be retracted
156	    // from here, but the preference can still be honored going forward: if
157	    // we're still waiting on it (haven't fallen through to the keypad yet),
158	    // switch to it proactively — exactly as if the user had tapped "Usar
159	    // PIN" themselves. A `false` -> `true` change is deliberately left
160	    // alone: re-triggering biometric out from under a user who's already
161	    // on the keypad (whether because it failed or because they chose "Usar
162	    // PIN") would be a surprise, not a fix, and PIN remains the access
163	    // method regardless either way (Boundaries).
164	    if (oldWidget.attemptBiometricFirst &&
165	        !widget.attemptBiometricFirst &&
166	        !_showPinKeypad) {
167	      _useManualPin();
168	    }
169	  }
