220	  Future<void> _announce(String message) async {
221	    if (!mounted) {
222	      return;
223	    }
224	    await SemanticsService.sendAnnouncement(
225	      View.of(context),
226	      message,
227	      TextDirection.ltr,
228	    );
229	  }
